import SwiftUI

/// The command examples describe the local implementation, not executable UI actions.
/// Keep this content aligned with Onboarding.swift, Engine.swift and DeviceHelpers/src.
enum OperationHelpTopic: String {
    case preparation
    case diagnosticADB
    case componentCleanup
    case firmwareSupport
    case imei

    var title: String {
        switch self {
        case .firmwareSupport: return "Данные для адаптации прошивки"
        case .componentCleanup: return "Очистка данных агента, VPN и страниц"
        case .diagnosticADB: return "Как включается и выключается ADB"
        case .preparation: return "Как выполняется подготовка модема"
        case .imei: return "Как записываются IMEI"
        }
    }

    var accessibilityLabel: String {
        switch self {
        case .firmwareSupport: return "Подробно о сборе данных для адаптации"
        case .componentCleanup: return "Подробно об очистке компонентов"
        case .diagnosticADB: return "Подробно о переключении ADB"
        case .preparation: return "Подробно о подготовке модема"
        case .imei: return "Подробно о записи IMEI"
        }
    }

    var introduction: String {
        switch self {
        case .firmwareSupport: return "Сбор помогает разобраться с другой прошивкой, например когда русификация экрана не поддерживает её бинарник. Он читает выбранный модем через уже настроенное SSH-подключение; агент и проверенный профиль B31 не требуются. Открытие справки и переход в раздел не запускают сбор."
        case .componentCleanup: return "Для переустановки после ошибки или заводского сброса: включите флажок рядом с кнопкой подготовки и введите новый пароль агента в параметрах первоначальной подготовки SSH. Приложение переустановит агент и SSH, затем очистит выбранные компоненты программы. Флажок выключен по умолчанию; открытие справки ничего не меняет."
        case .diagnosticADB: return "ADB нужен для первоначальной настройки SSH. Переключатель включает и выключает USB ADB через проверенное SSH-подключение на поддерживаемой конфигурации USB. После изменения приложение проверяет то же устройство и состояние USB. Открытие справки ничего не запускает."
        case .preparation:
            return "Подготовка создаёт постоянный доступ к модему: при необходимости включает ADB, устанавливает агент и настраивает SSH по ключу. VPN-компоненты устанавливаются отдельно кнопкой «Установить компоненты VPN» в меню VPN. Здесь описаны фактическая последовательность, изменяемые файлы и проверки приложения. Открытие этой справки ничего на модеме не выполняет."
        case .imei:
            return "Программа работает с одной или двумя активными записями NV550. Перед записью сохраняет проверенную копию, временно включает разрешение через EFS config и сверяет результат после перезагрузки. Неактивная NV1 не создаётся."
        }
    }

    var sections: [OperationHelpSection] {
        switch self {
        case .firmwareSupport: return Self.firmwareSupportSections
        case .componentCleanup: return Self.componentCleanupSections
        case .diagnosticADB: return Self.diagnosticADBSections
        case .preparation: return Self.preparationSections
        case .imei: return Self.imeiSections
        }
    }

    private static let firmwareSupportSections: [OperationHelpSection] = [
        .init("Что сохраняется", "Свежий технический отчёт по функциям программы, структура API, сведения о службах и ядре, исходные файлы экрана, сетевых и модемных компонентов, библиотеки DIAG/QMI/RIL, языки и шрифты. В архив входят версии и контрольные суммы файлов, состояние компонентов и очищенный журнал программы. Отсутствующие файлы и неудачные запросы перечислены отдельно."),
        .init("Исследование IMEI и eSIM", "Через SSH временно запускаются помощники чтения: ответы NV550, структура EFS config и состояние карт и слотов через QMI. Сохраняются коды ответов, размеры и результаты проверок, без IMEI, ICCID, EID и содержимого NV/config. Для съёмной eUICC и встроенной eSIM соберите отдельные ZIP, предварительно выбрав нужную SIM штатным способом и дождавшись её готовности. Программа сама не переключает SIM; номера слотов сохраняются без догадок об их назначении. Эти данные нужны для адаптации и не подтверждают возможность записи IMEI или установки eSIM."),
        .init("Что не меняется", "Сбор не записывает NV/config, не меняет IMEI, не перезапускает радио, не переключает слот и не выполняет APDU-команды или операции с профилями eSIM. Службы не перезапускаются. Временные помощники удаляются после чтения. Пароли, ключи, профили, настройки пользователя и полный образ флеш-памяти в архив не включаются."),
        .init("Как используется архив", "ZIP сохраняется только в выбранный вами файл и автоматически никуда не отправляется. Файлы прошивки передавайте лично для исследования, а не публикуйте как часть приложения. Недоступность отдельного диагностического запроса отмечается в архиве; успешное чтение само по себе не разрешает запись на неподдерживаемую прошивку.")
    ]

    private static let componentCleanupSections: [OperationHelpSection] = [
        .init("Архив перед удалением", "Перед заменой сохраняются исходные файлы агента и SSH. Перед очисткой компоненты программы и их настройки скачиваются в архив ComponentBackups на Mac и проверяются по контрольной сумме. После подтверждённого завершения удаляются только принадлежащие приложению временные файлы; незавершённые и неподтверждённые данные сохраняются."),
        .init("Что остаётся и что проверяется", "Очищаются компоненты VPN, его профили и настройки Wi-Fi с VPN; дополнительные страницы на экране модема, их выбор и порядок; веб-панель агента и данные установщика агента. Переустановленный агент с новым паролем, подготовленный SSH-доступ и резервные копии остаются. IMEI, SIM и профили eSIM не меняются. Настройки TTL, локализация экрана, пользователи SSH, SSClash, диагностические утилиты и остальные штатные настройки сохраняются. После проверки архива программа сама останавливает свой VPN и очищает его компоненты. Посторонние файлы и службы сохраняются. После очистки дополнительные компоненты можно установить заново соответствующими кнопками."),
        .init("Продолжение после ошибки", "Подготовка и очистка имеют отдельные журналы. Если очистка прервана, кнопка продолжает только её: пароль агента не меняется повторно и установка SSH не запускается заново. До отправки удаления доступна кнопка «Отменить очистку»: приложение проверит по SSH, что очистка не началась. Уже созданные архивы и журнал сохранятся. При неизвестном результате отмена не выполняется и журнал сохраняется.")
    ]

    private static let diagnosticADBSections: [OperationHelpSection] = [
        .init("1. Все обычные операции — через SSH", "Сведения, исследование прошивки, диагностика и управление выполняются через SSH. ADB используется для первоначальной подготовки SSH. Штатный Web и веб-панель агента открываются в браузере."),
        .init("2. Переключение USB ADB", "После успешной подготовки SSH приложение отключает ADB и удаляет строку его автозапуска, добавленную при подготовке. Переключатель ADB в параметрах подключения позволяет изменить это состояние вручную. Перед изменением сохраняется копия rc.local; остальные USB-функции сохраняются. Сетевое подключение по USB может кратко прерваться. Приложение повторно подключается по SSH и подтверждает результат. Если подтверждение не получено, возвращаются исходная конфигурация USB и автозапуск."),
        .init("3. Первоначальная подготовка", "Сначала проверяется уже настроенный SSH, затем работающий root USB ADB. Если ADB не подтверждён, приложение пробует известный штатный USB debug один раз: когда метод объявлен или список методов недоступен. Явное отсутствие метода пропускает этот шаг. Если доступа всё ещё нет, свежий бэкап проверяется по ключу, формату и штатному USB-блоку перед восстановлением. Название прошивки само по себе не разрешает и не запрещает этот путь. Бэкап и журнал сохраняются; отправленные изменения не повторяются при продолжении."),
        .init("4. Проверка и ограничения", "Неопределённое состояние показывается отдельно от выключенного ADB. Переключение недоступно при открытом терминале, другой операции, незавершённой подготовке, записи IMEI или восстановлении. Для неподдерживаемой конфигурации отображается причина; приложение не выбирает другой транспорт управления автоматически."),
    ]

    private static let preparationSections: [OperationHelpSection] = [
        .init("Проверить ключ бэкапа", "Отдельная кнопка в параметрах первоначальной подготовки требует только адрес модема и пароль штатного Web. Приложение читает версии прошивки, создаёт и скачивает свежий зашифрованный бэкап, повторно проверяет идентичность, затем проверяет расшифровку и структуру архива. Пустое поле пробует известный ключ как кандидат на любой прошивке; ручное значение не подменяется. Оригинал сохраняется локально в BackupKeyChecks/<UUID>, расшифрованные файлы на диск не записываются.\n\nРезультат содержит версии, число записей и SHA-256 зашифрованного архива. Проверка не включает ADB, не загружает бэкап на модем, не восстанавливает настройки и не устанавливает SSH или агент. Успех подтверждает только ключ и формат архива; ограничения операций записи остаются прежними."),
        .init("1. Начало подготовки: вход и резервная копия", "Уже настроенный SSH проверяется без паролей Web и агента. Для новой установки нужен root USB ADB и пароль нового агента. Пароль штатного Web нужен только для включения ADB через Web. Приложение берёт локальную блокировку и проверяет незавершённые операции.\n\nПри необходимости входа в Web используются штатный challenge и хэш пароля. Затем читаются IMEI и версии прошивки выбранного устройства. Название версии не блокирует первоначальную подготовку. Неверный пароль не подбирается автоматически.\n\nРаботающие SSH/ADB и успешное штатное переключение USB не требуют бэкапа. Только перед резервным способом создаётся и скачивается свежий зашифрованный архив; повторно проверяется идентичность. Оригинал, identity.json и SHA-256 сохраняются локально. Пустое поле пробует известный ключ формата; ручное значение не подменяется. Пароли, ключ бэкапа и веб-сессия в журнал этапов не записываются.", commands: "POST http://<modem>/ubus/\nzwrt_web.web_login_info {}\nzwrt_web.web_login {\"password\":\"<challenge hash>\"}\nzwrt_web.device_info {}\nzwrt_mc.device.manager.device_backup_proc {\"procType\":\"web\"}\nGET http://<modem>/backup/back_parameter\nSetupBackups/<UUID>/back_parameter.original\nsetup-pending.json"),
        .init("2. Если SSH или ADB уже работает", "Работающий SSH проверяется с выбранным ключом и доверием к серверу; агент, пароль Web и известная версия прошивки для повторного использования SSH не нужны. Если SSH нет, программа проверяет физический USB ADB. Сетевые ADB-устройства и эмуляторы не подменяют USB-модем.\n\nУже работающий root Linux ARM64 ADB не запускает включение USB или восстановление. Перед установкой вновь проверяются устройство, загрузка и измеренные компоненты. Для неизвестного набора компонентов используется существующий профиль диагностического доступа с ограниченным агентом; совместимость IMEI, eSIM и других операций проверяется отдельно. Структурные проверки установщика и хэши встроенных файлов сохраняются.", commands: "adb devices -l\nadb -d get-serialno\nadb -s <serial> shell <identity-check>\nid -u\nuname -m\nsha256sum /firmware/image/modem.b16 /usr/bin/diag-router\ncat /sys/block/mmcblk0/device/cid\nubus call zwrt_web device_info '{}'"),
        .init("3. Штатное переключение USB", "Приложение читает список методов zwrt_bsp.usb. Объявленный set с аргументом mode или недоступная интроспекция допускают один известный запрос mode=debug. Если список явно не содержит нужный метод, этот шаг пропускается. Другие factory-команды и пароли не подбираются.\n\nПеред запросом повторно проверяется Web-устройство, а намерение сохраняется в журнал. После запроса до 90 секунд проверяется реальный root USB ADB того же модема. Ответ RPC сам по себе не подтверждает доступ. Команда после обрыва не повторяется. Если ADB не появился, новый вход в Web и повторная идентификация обязательны перед проверкой свежего бэкапа.", commands: "POST /ubus/\n{\"jsonrpc\":\"2.0\",\"id\":1,\"method\":\"list\",\"params\":[\"zwrt_bsp.usb\"]}\n# After login, one call:\nzwrt_bsp.usb.set {\"mode\":\"debug\"}\n# Repeated verification only:\nadb devices -l\nadb -s <serial> shell <identity-check>"),
        .init("4. Проверенный формат бэкапа", "Свежий архив проверяется по OpenSSL Salted__, расшифровке, gzip/tar, внутреннему MD5, именам файлов и метаданным. Для изменения rc.local первый исполняемый блок должен точно соответствовать известному штатному USB-блоку с проверкой режимов 1/2 и FOTA. Упоминание usb_op в комментарии, строке или постороннем коде недостаточно; дополнительные обращения к USB отклоняются.\n\nДобавляется только строка включения ADB после #!/bin/sh. Остальные байты и записи сохраняются и проверяются. Архив заново шифруется и контрольным образом расшифровывается. Перед загрузкой и восстановлением повторно сверяется Web-идентичность; загрузчик подтверждает SHA-256. Восстановление отправляется один раз, затем проверяется фактический root ADB. Если строка уже была в исходном архиве, обычная подготовка не повторяет восстановление; диагностическое включение может запросить одну перезагрузку с сохранённым намерением.\n\nНеизвестный формат или неподходящий USB-блок останавливают этот способ. Успешная отдельная проверка ключа не заменяет проверку шаблона перед записью.", commands: "# Added inside the backup, executed at boot:\necho 1 > /sys/class/android_usb/android0/usb_op\nPOST http://<modem>/cgi-bin/cgi-upload\n  filename=/tmp/back_parameter\n  filedata=<verified encrypted backup>\nzwrt_mc.device.manager.device_restore_proc {\"procType\":\"web\"}\nSetupBackups/<UUID>/back_parameter.adb-only"),
        .init("5. Ошибки подключения и границы поддержки", "После включения ADB приложение ждёт готовый физический USB-модем и проверяет root, Linux ARM64, идентичность, CID и фактические хэши компонентов. Название прошивки не заменяет эти проверки. При нескольких устройствах первый serial не выбирается. Каждый shell-вызов должен вернуть проверенный удалённый код завершения.\n\nПосле подтверждения ADB используется подходящий установщик: известный профиль либо общий linux-arm64-access. Общий профиль проверяет права каталогов, автозапуск и хэши переданных файлов. Агент предоставляет информацию и управление; каждая операция проверяет необходимые ей компоненты. Исследование прошивки выполняет программа по SSH. Заводские пароли и скрытые factory-методы не перебираются."),
        .init("6. Подготовка каталогов и передача файлов", "До установки скрипт проверяет точные хэши, CID, доступные команды, типы и права каталогов, доступность записи и исполнения в /data, /etc и используемых точках монтирования, синтаксис rc.local, отсутствие чужой операции и свободное место: не менее 16 МиБ в /data и 2 МиБ в /etc.\n\nПриложение создаёт собственный каталог /data/zte-imei-studio с правами 700 под проверенным /data. Штатные /data/local/tmp и /data/bin могут иметь права 777; менять их права для установки не требуется. Каталог каждой установки создаётся внутри собственного каталога с правами 700 и маркером владельца.\n\nВ него через adb push передаются zte-agent, dropbear, setup-agent.sh, start_zte_imei_studio.sh, открытый ключ id_ed25519.pub и сценарий запуска агента. Каждый файл сначала поступает под уникальным incoming-именем, получает права 600, проверяется по SHA-256 и только затем переименовывается. После проверки хэша и формата исполняемые файлы получают права 700 перед проверкой запуска. Удалённый код завершения shell проверяется отдельно от кода самого процесса adb.", commands: #"""
        # Упрощённые шаблоны; проверки владельца/прав выполняются до mkdir.
        mkdir -m 700 /data/zte-imei-studio
        mkdir -m 700 /data/zte-imei-studio/stage-<UUID>
        adb -s <serial> push <файл> <stage>/incoming-<UUID>
        adb -s <serial> shell 'chmod 600 <incoming>; sha256sum <incoming>'
        sh <stage>/setup-agent.sh <stage> <CID> <SHA256-агента> \
          <SHA256-dropbear> <SHA256-открытого-ключа> \
          <b31|b02-experimental> <SHA256-прошивки> <SHA256-diag-router>
        """#),
        .init("7. Что устанавливается и сохраняется на модеме", "До первой постоянной правки установщик повторно проверяет устройство и создаёт приватный журнал /data/zte-imei-studio/installations/<UUID>. В before сохраняются исходные версии всех затрагиваемых существующих файлов, вместе с отметками их наличия и контрольными суммами. Каждая замена идёт через временный файл и переименование.\n\nНовый агент устанавливается в /data/zte-agent, его запуск — в /data/zte-imei-studio/start_zte_agent.sh. Заданный пароль агента хранится в этом root-сценарии с правами 700 как ZTE_AGENT_PASSWORD. При обычной подготовке корректный существующий файл запуска и пароль сохраняются; неработающий старый агент заменяется текущей сборкой с резервной копией. Принудительная подготовка сохраняет компоненты перед заменой, устанавливает текущий агент и применяет введённый пароль. Агент слушает порт 9090.\n\nDropbear и dropbearkey размещаются в /data/zte-imei-studio/bin. Открытый ключ приложения добавляется в /etc/dropbear/authorized_keys с сохранением других ключей. При отсутствии создаются серверные ключи Ed25519/RSA.\n\nВ /etc/rc.local добавляется запуск /data/zte-imei-studio/start_zte_imei_studio.sh перед первым exit 0. Существующие строки сохраняются. Этот сценарий запускает отсутствующий агент и SSH на порту 2222; успех подтверждается принадлежащим приложению слушателем на порту 2222. Новый SSH настроен на ключи, без входа по паролю.", commands: #"""
        # Постоянная строка автозапуска:
        sh /data/zte-imei-studio/start_zte_imei_studio.sh

        # Запуск нового слушателя SSH:
        /data/zte-imei-studio/bin/dropbear -s -P /var/run/zte-imei-dropbear.pid -p 2222 \
          -r /etc/dropbear/dropbear_ed25519_host_key \
          -r /etc/dropbear/dropbear_rsa_host_key
        """#),
        .init("8. Ключ SSH и итоговая проверка", "На Mac создаётся или повторно используется собственная пара SSH Ed25519. Закрытый ключ остаётся на Mac с правами 600; на модем передаётся только открытая часть. Ключ сервера читается через проверенный ADB, с повторной сверкой CID до и после чтения, и записывается в отдельный known_hosts для адреса модема и порта 2222. Последующие SSH-команды используют StrictHostKeyChecking=yes.\n\nПосле установки сверяются идентичности ADB и SSH, загрузка и фактические компоненты. Процесс агента проверяется по /proc/<pid>/exe, для нового агента проверяется вход заданным паролем. Готовность SSH не разрешает операции с NV: они проверяются отдельно.\n\nТолько после этих проверок установщик получает --commit, сверяет after.sha256 и помечает журнал завершённым. Приложение сохраняет параметры SSH, подключается и обновляет данные разделов. Временные переданные файлы удаляются; приватные снимки восстановления остаются.", commands: #"""
        # На Mac, только если своей пары ключей ещё нет:
        ssh-keygen -q -t ed25519 -N '' -C 'ZTE IMEI Studio' -f <ключ-Mac>
        # Через проверенный ADB:
        /data/zte-imei-studio/bin/dropbearkey -y -f /etc/dropbear/dropbear_ed25519_host_key
        # Проверка входа агента через SSH; пароль передаётся через stdin:
        curl --noproxy '*' --fail --silent --show-error \
          -H 'Content-Type: application/json' --data-binary @- \
          http://<адрес>:9090/api/auth/login
        sh <stage>/setup-agent.sh --commit <журнал> <CID> \
          <профиль> <SHA256-прошивки> <SHA256-diag-router>
        """#),
        .init("9. Если подготовка прервалась", "Локальный setup-pending.json сохраняет устройство и стадию операции. Если восстановление бэкапа уже запрошено, оно автоматически не повторяется. Если установка уже запрошена, приложение сначала читает удалённый журнал; автоматическое завершение допускается только из ready или complete, после проверки SSH и устройства. Незавершённые ранние стадии сохраняются для разбора и восстановления; установка не объявляется успешной и не запускается заново поверх неизвестного состояния.\n\nПодготовка изменяет перечисленные файлы настроек и доступа. Она не устанавливает плитки или русификацию, не записывает новые IMEI, не перемонтирует /usr/zte_web в rw и не прошивает раздел ZTEDATA. Оригинальный Web-архив и журнал установки находятся на Mac в данных приложения: SetupBackups/<UUID>. Фактические команды и результаты доступны в журнале действий.")
    ]

    private static let imeiSections: [OperationHelpSection] = [
        .init("1. Определение активных IMEI", "По SSH проверяются устройство, прошивка и diag-router. NV0 должен читаться и полностью совпадать с legacy NV550. NV1 либо читается, либо возвращает точный статус NV_NOTACTIVE_S (5). Ошибки транспорта и другие статусы останавливают операцию. API проверяется только для активных записей.", commands: "<zte_nv> --snapshot-available"),
        .init("2. Проверенная копия перед записью", "Сохраняются полные 128 байт каждой активной записи, EFS config и манифест с контрольными суммами. Для одного IMEI используются nv0.bin и config.bin; старые парные копии сохраняют совместимость. Число записей копии должно совпадать с текущим модемом. В каждом NV изменяются только первые 9 байт IMEI, остальные 119 байт сохраняются.", commands: "<zte_config_read> --read-config"),
        .init("3. Запись и проверка", "После проверки копии временно включается config102 и выполняется перезагрузка. План содержит исходные и целевые записи: 256 байт для одного IMEI, 512 для двух. После каждого шага проверяются все активные записи, их число и legacy-алиас. Затем возвращается исходный config и выполняется заключительная перезагрузка с проверкой NV и API. На B04 режим EFS config 0644 сохраняется при замене и откате.", commands: "<zte_nv> --apply-plan <план>"),
        .init("4. Ошибка или восстановление", "При обрыве сохраняются журнал и копия. Продолжение сверяет устройство, число записей и полные исходные либо целевые данные. Неизвестные данные не перезаписываются. Восстановление выбранной копии сначала сохраняет текущее состояние. Допуск определяется фактическими форматами NV/EFS и ABI diag-router. Аппаратная запись проверена на B31; запись на реальных B28 и B04 в этом цикле ещё не подтверждена.")
    ]
}

struct OperationHelpSection: Identifiable {
    let title: String
    let body: String
    let commands: String?
    var id: String { title }

    init(_ title: String, _ body: String, commands: String? = nil) {
        self.title = title
        self.body = body
        self.commands = commands
    }
}

@MainActor
struct OperationInfoButton: View {
    let topic: OperationHelpTopic
    @StudioState private var isPresented = false

    var body: some View {
        Button { isPresented = true } label: {
            Image(systemName: "info.circle")
                .font(.system(size: 16, weight: .medium))
                .foregroundStyle(StudioStyle.secondary)
                .frame(width: 28, height: 28)
                .contentShape(Rectangle())
        }
        .buttonStyle(.plain)
        .help(L10n.text(topic.accessibilityLabel))
        .accessibilityLabel(L10n.text(topic.accessibilityLabel))
        .accessibilityIdentifier("operation-help-" + topic.rawValue)
        .sheet(isPresented: $isPresented) { OperationHelpSheet(topic: topic) }
    }
}

@MainActor
struct OperationHelpSheet: View {
    let topic: OperationHelpTopic
    @Environment(\.dismiss) private var dismiss

    var body: some View {
        VStack(spacing: 0) {
            HStack(alignment: .top, spacing: 16) {
                Image(systemName: "info.circle.fill")
                    .font(.system(size: 24)).foregroundStyle(StudioStyle.accent)
                VStack(alignment: .leading, spacing: 5) {
                    Text(L10n.text(topic.title)).font(.system(size: 20, weight: .semibold))
                    Text(L10n.text("Последовательность, команды и сохраняемые данные"))
                        .font(.system(size: 12)).foregroundStyle(StudioStyle.secondary)
                }
                Spacer(minLength: 0)
                Button(L10n.text("Закрыть")) { dismiss() }
                    .keyboardShortcut(.cancelAction)
                    .accessibilityIdentifier("operation-help-close")
            }
            .padding(24)
            Divider().overlay(StudioStyle.line)
            ScrollView {
                VStack(alignment: .leading, spacing: 24) {
                    Text(L10n.text(topic.introduction))
                        .font(.system(size: 13)).lineSpacing(4)
                    Text(L10n.text("В примерах <…> обозначает адрес, UUID, путь, хэш или другой параметр конкретной операции. Пароли и ключи здесь не показываются. Приведены основные вызовы; приложение дополнительно выполняет описанные проверки и защитные обёртки. Команды не нужно вводить вручную."))
                        .font(.system(size: 12)).lineSpacing(3)
                        .foregroundStyle(StudioStyle.secondary)
                        .padding(14)
                        .background(StudioStyle.elevated, in: RoundedRectangle(cornerRadius: 10))
                    ForEach(topic.sections) { section in
                        VStack(alignment: .leading, spacing: 10) {
                            Text(L10n.text(section.title)).font(.system(size: 15, weight: .semibold))
                            Text(L10n.text(section.body)).font(.system(size: 13)).lineSpacing(4)
                            if let commands = section.commands {
                                Text(commands)
                                    .font(.system(size: 11, design: .monospaced))
                                    .lineSpacing(3)
                                    .fixedSize(horizontal: false, vertical: true)
                                    .frame(maxWidth: .infinity, alignment: .leading)
                                    .padding(14)
                                    .background(StudioStyle.canvas, in: RoundedRectangle(cornerRadius: 10))
                                    .overlay(RoundedRectangle(cornerRadius: 10).stroke(StudioStyle.line))
                            }
                        }
                        .frame(maxWidth: .infinity, alignment: .leading)
                    }
                }
                .textSelection(.enabled)
                .fixedSize(horizontal: false, vertical: true)
                .padding(24)
                .frame(maxWidth: .infinity, alignment: .leading)
            }
        }
        .frame(width: 740, height: 680)
        .foregroundStyle(StudioStyle.text)
        .background(StudioStyle.surface)
        .preferredColorScheme(.dark)
    }
}
